import Foundation

/// A key-click sound pack from shared/sounds/packs.json (generated by tools/build_sounds.py).
struct SoundPack: Decodable, Equatable {
    let id: String
    /// Number of key sounds, `key1.wav` … `keyN.wav`.
    let keys: Int
    /// "by_key": each key always plays the same variant (musical packs); otherwise a variant is picked at random.
    let variation: String

    var variantByKey: Bool { variation == "by_key" }
}

enum SoundPacks {
    /// The system click (`UIDevice.playInputClick`); it has no files.
    static let system = "system"
    static let defaultPack = "mechanical"

    private struct Manifest: Decodable {
        let packs: [SoundPack]
    }

    static func load() -> [SoundPack] {
        guard let data = SharedResources.data("sounds/packs.json"),
              let manifest = try? JSONDecoder().decode(Manifest.self, from: data) else { return [] }
        return manifest.packs.filter { $0.keys > 0 }
    }

    /// The key sound variant a key plays: musical packs map each key to a fixed note, others vary at random.
    static func keyVariant(_ pack: SoundPack, label: String?, random: () -> Int = { Int.random(in: 0..<Int.max) }) -> Int {
        guard pack.keys > 1 else { return 0 }
        if pack.variantByKey, let scalar = label?.lowercased().unicodeScalars.first {
            return Int(scalar.value) % pack.keys
        }
        let value = random() % pack.keys
        return value < 0 ? value + pack.keys : value
    }
}
